var RUN = "_swe/edd/t038/ledger.json";
var DESCRIPTION = "Keep the evidence ledger of an Evidence-Driven Development task, and refuse every claim the evidence " + "does not back. The ledger, a JSON file, holds one row per acceptance criterion: its tests, its " + "evidence files, the script that made them, what they show, and its status (open, proven, user-check " + "or waived). Start a run's ledger with `init`, run `check` after every change to it, clear the run's " + "work folder with `prune` at the close, and take the report's table from `table`.";
